// UUIDv7 (RFC 9562) generated by the application (Postgres 17 has no
// uuidv7()). Monotonic within a process: ids sort in creation order even
// within one millisecond (method 3: a 12-bit counter in rand_a, reseeded each
// millisecond), which F-33 relies on to break created_at ties.
import { randomBytes } from "node:crypto";

export type IdGenerator = () => string;

function format(bytes: Uint8Array): string {
  const hex = Buffer.from(bytes).toString("hex");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

function build(ms: number, counter: number, tail: Uint8Array): string {
  const b = new Uint8Array(16);
  // 48-bit big-endian Unix milliseconds
  let t = ms;
  for (let i = 5; i >= 0; i--) {
    b[i] = t % 256;
    t = Math.floor(t / 256);
  }
  b[6] = 0x70 | ((counter >> 8) & 0x0f); // version 7 + counter high bits
  b[7] = counter & 0xff;
  b[8] = 0x80 | ((tail[0] ?? 0) & 0x3f); // variant 10
  for (let i = 9; i < 16; i++) b[i] = tail[i - 8] ?? 0;
  return format(b);
}

/**
 * A UUIDv7 generator. `now` defaults to the wall clock; ids follow wall time,
 * not a frozen test clock, but stay strictly increasing either way.
 */
export function createUuidV7Generator(
  now: () => number = Date.now,
  random: (n: number) => Uint8Array = randomBytes,
): IdGenerator {
  let lastMs = -1;
  let counter = 0;
  return () => {
    let ms = now();
    if (ms <= lastMs) {
      ms = lastMs;
      counter++;
      if (counter > 0xfff) {
        // Counter exhausted: borrow the next millisecond to stay monotonic.
        ms = lastMs + 1;
        counter = 0;
      }
    } else {
      counter = (random(2)[0] ?? 0) & 0x3ff; // leave headroom for increments
    }
    lastMs = ms;
    return build(ms, counter, random(8));
  };
}

/**
 * Deterministic UUIDv7s for the seed: a fixed start instant, one millisecond
 * apart, with a seeded PRNG for the random bits. Same seed, same ids.
 */
export function createDeterministicIdGenerator(
  startMs: number,
  seed: number,
): IdGenerator {
  let state = seed >>> 0 || 1;
  const random = (n: number): Uint8Array => {
    const out = new Uint8Array(n);
    for (let i = 0; i < n; i++) {
      // xorshift32
      state ^= state << 13;
      state >>>= 0;
      state ^= state >>> 17;
      state ^= state << 5;
      state >>>= 0;
      out[i] = state & 0xff;
    }
    return out;
  };
  let ms = startMs;
  return createUuidV7Generator(() => ms++, random);
}

export const defaultIdGenerator: IdGenerator = createUuidV7Generator();
